import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Techniques & Specializations","description":"","frontmatter":{},"headers":[],"relativePath":"guide/characters/techniques.md","filePath":"guide/characters/techniques.md"}'),r={name:"guide/characters/techniques.md"};function n(o,e,l,c,h,d){return i(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="techniques-specializations" tabindex="-1">Techniques &amp; Specializations <a class="header-anchor" href="#techniques-specializations" aria-label="Permalink to &quot;Techniques &amp; Specializations&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> These are intended changes, not confirmed live rules. <strong>Implementation/availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/game-design/characters/techniques-and-specialization.html">full design specification</a>.</p><h2 id="skill-is-capability-techniques-are-knowledge" tabindex="-1">Skill is capability; techniques are knowledge <a class="header-anchor" href="#skill-is-capability-techniques-are-knowledge" aria-label="Permalink to &quot;Skill is capability; techniques are knowledge&quot;">​</a></h2><p>A skilled carpenter does not automatically know Bowmaking. A skilled blacksmith may still lack a rare bladesmithing school. Skill helps execution; learned techniques open specific possibilities.</p><p>A practical profession path grows from skills, techniques, practice and reputation. Your longer-term identity is what other people know you for—perhaps especially durable bows or excellent field equipment.</p><h2 id="learning-through-the-world" tabindex="-1">Learning through the world <a class="header-anchor" href="#learning-through-the-world" aria-label="Permalink to &quot;Learning through the world&quot;">​</a></h2><p>Masters, academies, guilds, manuscripts, exploration, challenges, competitions, reputation and other players may teach knowledge. Reverse engineering may help in suitable disciplines. Fundamentals, Advanced Techniques and Master Techniques are possible levels of knowledge, not a giant perk tree.</p><p>Techniques should not all be mutually exclusive. Time, skill budget, practice and discovery should create specialization without forcing permanent classes.</p><h2 id="more-to-discover-after-100" tabindex="-1">More to discover after 100 <a class="header-anchor" href="#more-to-discover-after-100" aria-label="Permalink to &quot;More to discover after 100&quot;">​</a></h2><p>Two masters can know different materials and techniques. Advice can teach the player a process without granting the character the capability or knowledge to reproduce it automatically.</p><p>Exact teaching rights, knowledge persistence, custody and forgetting remain open. <a href="/Syrolands-Public/guide/professions/carpentry.html#bowmaking-and-fletching">Bowmaking</a> is a proposed Carpentry/Archery technique path; migration from any existing Bowcraft skill is unresolved.</p><p><a href="/Syrolands-Public/guide/characters/progression.html">Progression</a> · <a href="/Syrolands-Public/guide/characters/skills.html#learning-skills-and-finding-teachers">Teachers</a> · <a href="/Syrolands-Public/guide/professions/overview.html">Professions</a></p>',12)])])}const g=a(r,[["render",n]]);export{u as __pageData,g as default};
